mapper.select:
SELECT id, device_name, iot_id, note_name, product_id, product_name, function_name, access_location, data_value, alarm_time, processing_result, processor, processing_time, status, create_time, update_time, create_by, update_by, remark FROM device_data
AND iot_id = #{iotId}
AND function_name = #{functionId}
AND create_time >= FROM_UNIXTIME(#{startTime} / 1000)
AND create_time <= FROM_UNIXTIME(#{endTime} / 1000)
ORDER BY create_time DESC

SELECT id, device_id, binding_location, location_type, physical_location_type, device_name, note_name, product_id, produce_name, device_description, create_time, update_time, is_deleted, create_by, update_by, remark FROM device WHERE binding_location IN
#{location}
AND physical_location_type = #{physicalLocationType} AND is_deleted = 0

SELECT id, device_name, iot_id, note_name, product_id, product_name, function_name, access_location, data_value, alarm_time, processing_result, processor, processing_time, status, create_time, update_time, create_by, update_by, remark FROM device_data WHERE iot_id IN
#{iotId}
ORDER BY create_time DESC
